int pos = 2;
int step[4] = {3, -1, -6, 2};
for (int i = 0; i < 4; ++i) {
    pos += step[i];
    if (pos < 0) pos = 0;
}
cout << pos << "\n";

#include <iostream>
using namespace std;
int f(int n) {
    if (n == 0) return 1;
    return f(n - 1) + 2;
}
int main() { cout << f(3) << "\n"; }

int n = 4, count = 0;
for (int i = 0; i < n; ++i) ++count;
for (int j = 0; j < n; ++j) ++count;
cout << count << "\n";

#include <iostream>
using namespace std;
void show(int n) {
    if (n == 0) return;
    cout << n;
    show(n - 1);
}
int main() { show(3); cout << "\n"; }

int count = 0;
for (int i = 1; i <= 4; ++i) {
    for (int j = 1; j <= i; ++j) ++count;
}
cout << count << "\n";

int s = 0;
for (int i = 1; i <= 6; ++i) {
    if (i == 4) break;
    if (i % 2 == 0) continue;
    s += i;
}
cout << s << "\n";
